<?php
declare(strict_types=1);
namespace App\Form\Type;
use App\Entity\Leasing\{LeasingConfiguration,LeasingFactor}; use Symfony\Bridge\Doctrine\Form\Type\EntityType; use Symfony\Component\Form\AbstractType; use Symfony\Component\Form\Extension\Core\Type\{CheckboxType,EmailType,MoneyType,SubmitType,TextareaType,TextType}; use Symfony\Component\Form\FormBuilderInterface; use Symfony\Component\OptionsResolver\OptionsResolver;
final class LeasingConfigurationType extends AbstractType { public function buildForm(FormBuilderInterface $b,array $o):void{$b->add('enabled',CheckboxType::class,['required'=>false,'label'=>'cardnext.leasing.enabled'])->add('providerName',TextType::class,['label'=>'cardnext.leasing.provider'])->add('minimumNetAmount',MoneyType::class,['currency'=>'EUR','divisor'=>100,'label'=>'cardnext.leasing.minimum'])->add('defaultFactor',EntityType::class,['class'=>LeasingFactor::class,'choice_label'=>'durationMonths','placeholder'=>'—','required'=>false,'label'=>'cardnext.leasing.default_duration'])->add('frontendNotice',TextareaType::class,['label'=>'cardnext.leasing.notice'])->add('ctaText',TextType::class,['label'=>'cardnext.leasing.cta'])->add('notificationEmail',EmailType::class,['required'=>false,'label'=>'cardnext.leasing.notification_email'])->add('save',SubmitType::class,['label'=>'cardnext.ui.save']);}public function configureOptions(OptionsResolver $r):void{$r->setDefaults(['data_class'=>LeasingConfiguration::class]);}}
